window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ff3b959021ad3fce"]={"versions": [{"id": "FIG-ff3b959021ad3fce", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Speicherabbild zur Hardware-Objekt-Struktur im AUTOSAR CAN Driver (<code>Can</code>). Das Diagramm illustriert das tabellarische bzw. array-basierte Speicher-Layout von Hardware-Objekten (Mailboxen) im CAN-Controller für den Empfang und Versand von CAN-Nachrichten (HRH/HTH-Zuordnung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware Objects (Zeilen 1 bis 8)</strong>: Acht identisch strukturierte Puffer- bzw. Mailbox-Einträge des CAN-Controllers, links mit Zuordnungsstrichen für Hardware-Handles versehen.\n</li><li><strong>ID (Identifier-Feld)</strong>: Erste Spalte jedes Hardware-Objekts zur Aufnahme des CAN-Identifiers (Standard/Extended CAN ID).\n</li><li><strong>DLC (Data Length Code)</strong>: Zweite Spalte jedes Hardware-Objekts zur Speicherung bzw. Konfiguration der Nutzdatenlänge.\n</li><li><strong>SDU (Service Data Unit)</strong>: Dritte Spalte jedes Hardware-Objekts zur Speicherung des Daten-Payloads (CAN L-SDU bzw. Datenbytes).\n</li><li><strong>Geschweifte Klammer (oben)</strong>: Umspannt die Gesamtbreite der Mailbox-Definition (ID, DLC, SDU) als zusammenhängende Repräsentation eines Hardware-Objekts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicher- bzw. Zuordnungsstruktur dar. Es zeigt keinen dynamischen Sequenzablauf, sondern die einheitliche Aufteilung jedes Hardware-Objekts in die logischen Felder <code>ID</code>, <code>DLC</code> und <code>SDU</code>. Treiber-intern adressieren HTH (Hardware Transmit Handle) und HRH (Hardware Receive Handle) diese Pufferzeilen für Sende- und Empfangsoperationen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ veranschaulicht das Diagramm die interne Struktur der Mailboxen bzw. Hardware-Objekte im CAN-Controller für AUTOSAR CanDriver-Implementierungen. Jedes konfigurierte Hardware-Objekt muss mindestens die Informationselemente Identifier, Data Length Code und SDU-Nutzdaten abbilden können, unabhängig von der konkreten Mikrocontroller-Registerarchitektur.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-07bb84e80ad3962a", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Speicherabbild zur Hardware-Objekt-Struktur im AUTOSAR CAN Driver (<code>Can</code>). Das Diagramm illustriert das tabellarische bzw. array-basierte Speicher-Layout von Hardware-Objekten (Mailboxen) im CAN-Controller für den Empfang und Versand von CAN-Nachrichten (HRH/HTH-Zuordnung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware Objects (Zeilen 1 bis 8)</strong>: Acht identisch strukturierte Puffer- bzw. Mailbox-Einträge des CAN-Controllers, links mit Zuordnungsstrichen für Hardware-Handles versehen.\n</li><li><strong>ID (Identifier-Feld)</strong>: Erste Spalte jedes Hardware-Objekts zur Aufnahme des CAN-Identifiers (Standard/Extended CAN ID).\n</li><li><strong>DLC (Data Length Code)</strong>: Zweite Spalte jedes Hardware-Objekts zur Speicherung bzw. Konfiguration der Nutzdatenlänge.\n</li><li><strong>SDU (Service Data Unit)</strong>: Dritte Spalte jedes Hardware-Objekts zur Speicherung des Daten-Payloads (CAN L-SDU bzw. Datenbytes).\n</li><li><strong>Geschweifte Klammer (oben)</strong>: Umspannt die Gesamtbreite der Mailbox-Definition (ID, DLC, SDU) als zusammenhängende Repräsentation eines Hardware-Objekts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicher- bzw. Zuordnungsstruktur dar. Es zeigt keinen dynamischen Sequenzablauf, sondern die einheitliche Aufteilung jedes Hardware-Objekts in die logischen Felder <code>ID</code>, <code>DLC</code> und <code>SDU</code>. Treiber-intern adressieren HTH (Hardware Transmit Handle) und HRH (Hardware Receive Handle) diese Pufferzeilen für Sende- und Empfangsoperationen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ veranschaulicht das Diagramm die interne Struktur der Mailboxen bzw. Hardware-Objekte im CAN-Controller für AUTOSAR CanDriver-Implementierungen. Jedes konfigurierte Hardware-Objekt muss mindestens die Informationselemente Identifier, Data Length Code und SDU-Nutzdaten abbilden können, unabhängig von der konkreten Mikrocontroller-Registerarchitektur.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c984c8bb4cb98e25", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Speicherabbild zur Hardware-Objekt-Struktur im AUTOSAR CAN Driver (<code>Can</code>). Das Diagramm illustriert das tabellarische bzw. array-basierte Speicher-Layout von Hardware-Objekten (Mailboxen) im CAN-Controller für den Empfang und Versand von CAN-Nachrichten (HRH/HTH-Zuordnung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware Objects (Zeilen 1 bis 8)</strong>: Acht identisch strukturierte Puffer- bzw. Mailbox-Einträge des CAN-Controllers, links mit Zuordnungsstrichen für Hardware-Handles versehen.\n</li><li><strong>ID (Identifier-Feld)</strong>: Erste Spalte jedes Hardware-Objekts zur Aufnahme des CAN-Identifiers (Standard/Extended CAN ID).\n</li><li><strong>DLC (Data Length Code)</strong>: Zweite Spalte jedes Hardware-Objekts zur Speicherung bzw. Konfiguration der Nutzdatenlänge.\n</li><li><strong>SDU (Service Data Unit)</strong>: Dritte Spalte jedes Hardware-Objekts zur Speicherung des Daten-Payloads (CAN L-SDU bzw. Datenbytes).\n</li><li><strong>Geschweifte Klammer (oben)</strong>: Umspannt die Gesamtbreite der Mailbox-Definition (ID, DLC, SDU) als zusammenhängende Repräsentation eines Hardware-Objekts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicher- bzw. Zuordnungsstruktur dar. Es zeigt keinen dynamischen Sequenzablauf, sondern die einheitliche Aufteilung jedes Hardware-Objekts in die logischen Felder <code>ID</code>, <code>DLC</code> und <code>SDU</code>. Treiber-intern adressieren HTH (Hardware Transmit Handle) und HRH (Hardware Receive Handle) diese Pufferzeilen für Sende- und Empfangsoperationen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ veranschaulicht das Diagramm die interne Struktur der Mailboxen bzw. Hardware-Objekte im CAN-Controller für AUTOSAR CanDriver-Implementierungen. Jedes konfigurierte Hardware-Objekt muss mindestens die Informationselemente Identifier, Data Length Code und SDU-Nutzdaten abbilden können, unabhängig von der konkreten Mikrocontroller-Registerarchitektur.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ff3b959021ad3fce", "to": "FIG-07bb84e80ad3962a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-07bb84e80ad3962a", "to": "FIG-c984c8bb4cb98e25", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c984c8bb4cb98e25", "to": "FIG-07bb84e80ad3962a", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
